}

test "scrape_twitter_card" {
    // Extracts Twitter Card metadata from a page
    allow_private_network();
    var gpa: std.heap.DebugAllocator(.{}) = .init;
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const url = if (std.c.getenv("MOCK_SERVER_SCRAPE_TWITTER_CARD")) |_pf| try std.fmt.allocPrint(allocator, "{s}", .{std.mem.span(_pf)}) else try std.fmt.allocPrint(allocator, "{s}/fixtures/scrape_twitter_card", .{if (std.c.getenv("MOCK_SERVER_URL")) |v| std.mem.span(v) else "http://localhost:8080"});
    defer allocator.free(url);
    const _result_json = try crawlberg.scrape("{}", url);
    defer std.heap.c_allocator.free(_result_json);
    var _parsed = try std.json.parseFromSlice(std.json.Value, allocator, _result_json, .{});
    defer _parsed.deinit();
    const result = &_parsed.value;
    try testing.expectEqual(@as(i64, 200), result.object.get("status_code").?.integer);
    {
        const _ne = result.object.get("metadata").?.object.get("twitter_card").?;
        try testing.expect(switch (_ne) {
            .null => false,
            .string => |_s| _s.len > 0,
            .array => |_a| _a.items.len > 0,
            .object => |_o| _o.count() > 0,
            else => true,
        });
    }
    try testing.expectEqualStrings("summary_large_image", std.mem.trim(u8, result.object.get("metadata").?.object.get("twitter_card").?.string, " \n\r\t"));
    try testing.expectEqualStrings("New Product Launch", std.mem.trim(u8, result.object.get("metadata").?.object.get("twitter_title").?.string, " \n\r\t"));
}
